use std::io

fn main() {
    let first = io::read_line() ?? "0"
    let t = first.trim().parse::<int>() ?? 0
    let limit = 200001
    let mut sieve: Vec<bool> = Vec::new()
    let mut i = 0
    while i < limit {
        sieve.push(true)
        i += 1
    }
    let mut cnt: Vec<int> = Vec::new()
    let mut last: Vec<int> = Vec::new()
    let mut c = 0
    let mut l = 0 - 1
    let mut p = 0
    while p < limit {
        if p >= 2 && sieve[p] {
            c += 1
            l = p
            let mut m = p * p
            while m < limit {
                sieve[m] = false
                m += p
            }
        }
        cnt.push(c)
        last.push(l)
        p += 1
    }
    let mut k = 0
    while k < t {
        let line = io::read_line() ?? "0"
        let n = line.trim().parse::<int>() ?? 0
        if last[n] < 0 {
            println("0 none")
        } else {
            println("${cnt[n]} ${last[n]}")
        }
        k += 1
    }
}

